function commitLine(commit: CommitReference) {
    return `${commit.commit.slice(0, 7)}: +${NUMBER_FORMAT.format(commit.insertions)} / -${NUMBER_FORMAT.format(commit.deletions)}`
}

function scopeName(scope: ActionUsageScope) {
    return scope === 'conversation' ? 'Conversation' : 'Action/card'
}

function scopeTooltip(
    definition: string,
    conversationValue: string | null,
    actionCardValue: string,
    scope: ActionUsageScope,
    activeDetails?: ReactNode,
) {
    const switchTarget = scope === 'conversation' ? 'Action/card' : 'Conversation'
    const interactionExplanation = conversationValue === null
        ? 'Conversation unavailable; clicking keeps Action/card scope.'
        : `Click to switch to ${switchTarget}.`

    return (
        <Stack spacing={0.5}>
            <Typography color="inherit" variant="caption">{definition}</Typography>
            <Typography color="inherit" variant="caption">
                Active scope: {scopeName(scope)}. {interactionExplanation}
            </Typography>
            <Typography color="inherit" variant="caption">
                Conversation{scope === 'conversation' ? ' (active)' : ''}: {conversationValue ?? 'unavailable'}
            </Typography>
            <Typography color="inherit" variant="caption">
                Action/card{scope === 'actionCard' ? ' (active)' : ''}: {actionCardValue}
            </Typography>
            {activeDetails}
        </Stack>
    )
}

function tokenValue(usage: AgentTokenUsage) {
    return `${NUMBER_FORMAT.format(usage.totalTokens)} tokens`
}

function changeValue(usage: AgentFileChangeUsage) {
    return `+${NUMBER_FORMAT.format(usage.insertions)} / -${NUMBER_FORMAT.format(usage.deletions)}`
}

function lineValue(usage: LineUsage) {
    const total = usage.insertions + usage.deletions

    return `${NUMBER_FORMAT.format(total)} lines (+${NUMBER_FORMAT.format(usage.insertions)} / -${NUMBER_FORMAT.format(usage.deletions)})`
}

/** Three shared-scope usage controls for one agent action on one card. */
export function ActionUsageSummary(props: ActionUsageSummaryProps) {
    const { actionId, cardInternalId, conversation, conversations, history, liveConversation, onToggleScope, scope } = props
    const scopedUsage = scopedActionUsage(
        conversations,
        liveConversation,
        conversation,
        history,
        actionId,
        cardInternalId,
    )
    const conversationUsage = scopedUsage.conversation
    const activeScope: ActionUsageScope = scope === 'conversation' && conversationUsage ? 'conversation' : 'actionCard'
    const activeUsage = activeScope === 'conversation' && conversationUsage
        ? conversationUsage
        : scopedUsage.actionCard
    const activeLines = activeUsage.lines
    const hasChanges = activeUsage.changes.insertions + activeUsage.changes.deletions > 0
    const totalLines = activeLines.insertions + activeLines.deletions
    const lineDetails = (
        <>
            <Typography color="inherit" variant="caption">
                files changed: {NUMBER_FORMAT.format(activeLines.filesChanged)}, insertions: {NUMBER_FORMAT.format(activeLines.insertions)},
                {' '}deletions: {NUMBER_FORMAT.format(activeLines.deletions)}
            </Typography>
            {activeLines.commits.map((commit, index) => (
                <Typography color="inherit" key={`${commit.repositoryRoot}\u0000${commit.commit}\u0000${index}`} variant="caption">
                    {commitLine(commit)}
                </Typography>
            ))}
        </>
    )
    const activeScopeName = scopeName(activeScope)
    return (
        <Box
            sx={{
                alignItems: 'center', display: 'flex', flexWrap: 'wrap', gap: 1, minWidth: 0,
                '@container (max-width: 420px)': { flexWrap: 'nowrap', gap: 0.5 },
            }}
        >
            <Tooltip describeChild title={scopeTooltip(
                'Tokens are cumulative provider token usage.',
                scopedUsage.conversation ? tokenValue(scopedUsage.conversation.tokens) : null,
                tokenValue(scopedUsage.actionCard.tokens),
                activeScope,
            )}>
                <ButtonBase
                    aria-label={`Tokens, ${activeScopeName} scope`}
                    onClick={onToggleScope}
                    sx={USAGE_CONTROL_SX}
                >
                    <Box
                        component="span"
                        data-usage-prefix
                        sx={{ '@container (max-width: 420px)': { display: 'none' } }}
                    >
                        tokens:{' '}
                    </Box>
                    {NUMBER_FORMAT.format(activeUsage.tokens.totalTokens)}
                </ButtonBase>
            </Tooltip>
            {hasChanges ? (
                <Tooltip describeChild title={scopeTooltip(
                    'Changes are additions and deletions across completed provider file-change patches.',
                    scopedUsage.conversation ? changeValue(scopedUsage.conversation.changes) : null,
                    changeValue(scopedUsage.actionCard.changes),
                    activeScope,
                )}>
                    <ButtonBase
                        aria-label={`Changes, ${activeScopeName} scope`}
                        onClick={onToggleScope}
                        sx={USAGE_CONTROL_SX}
                    >
                        <Box
                            component="span"
                            data-usage-prefix
                            sx={{ '@container (max-width: 420px)': { display: 'none' } }}
                        >
                            changes:&nbsp;
                        </Box>
                        <Box component="span" sx={{ color: 'success.main' }}>
                            +{NUMBER_FORMAT.format(activeUsage.changes.insertions)}
                        </Box>
                        &nbsp;/&nbsp;
                        <Box component="span" sx={{ color: 'error.main' }}>
                            -{NUMBER_FORMAT.format(activeUsage.changes.deletions)}
                        </Box>
                    </ButtonBase>
                </Tooltip>
            ) : null}
            {totalLines > 0 ? (
                <Tooltip describeChild title={scopeTooltip(
                    'Lines are additions plus deletions in captured Git commit diffs.',
                    scopedUsage.conversation ? lineValue(scopedUsage.conversation.lines) : null,
                    lineValue(scopedUsage.actionCard.lines),
                    activeScope,
                    lineDetails,
                )}>
                    <ButtonBase
                        aria-label={`Lines, ${activeScopeName} scope`}
                        onClick={onToggleScope}
                        sx={USAGE_CONTROL_SX}
                    >
                        <Box
                            component="span"
                            data-usage-prefix
                            sx={{ '@container (max-width: 420px)': { display: 'none' } }}
                        >
                            lines:{' '}
                        </Box>
                        {NUMBER_FORMAT.format(totalLines)}
                        &nbsp;(
                        <Box component="span" sx={{ color: 'success.main' }}>
                            +{NUMBER_FORMAT.format(activeLines.insertions)}
                        </Box>
                        &nbsp;/&nbsp;
                        <Box component="span" sx={{ color: 'error.main' }}>
                            -{NUMBER_FORMAT.format(activeLines.deletions)}
                        </Box>
                        )
                    </ButtonBase>
                </Tooltip>
            ) : null}
        </Box>
    )
}

import type { AgentConversation, AgentTokenUsage, ProjectSnapshot } from '../../data/data_types'
import { sumAgentTokenUsage } from '../../../../shared/agent_usage_math.mjs'
import type { AgentTokenUsageSummary } from '../../../../shared/agent_token_usage_summary.mjs'

export { sumAgentTokenUsage }

export interface AgentUsageVersion {
    name: string
    usage: AgentTokenUsage
}

export interface AgentFileChangeUsage {
    deletions: number
    insertions: number
}

export interface ProjectAgentUsage {
    archived: AgentUsageVersion
    current: AgentUsageVersion
    project: AgentTokenUsage
    releases: AgentUsageVersion[]
}

export function cardAgentTokenUsage(source: AgentConversation[] | ProjectSnapshot['activeCards'][number]): AgentTokenUsage {
    const conversations = Array.isArray(source) ? source : source.agentConversations

    return sumAgentTokenUsage(conversations.map(({ usage }) => usage))
}

/** Aggregate loaded conversations belonging to one action on one card. */
export function actionCardAgentTokenUsage(conversations: AgentConversation[], actionId: string, cardInternalId: string): AgentTokenUsage {
    const matchingUsage = conversations
        .filter((conversation) => conversation.actionId === actionId && conversation.cardInternalId === cardInternalId)
        .map(({ usage }) => usage)

    return sumAgentTokenUsage(matchingUsage)
}

/** Sum completed provider patches in one canonical conversation. */
export function conversationFileChangeUsage(conversation: AgentConversation | null): AgentFileChangeUsage | null {
    if (!conversation) return null
    let countedEvents = 0
    let deletions = 0
    let insertions = 0
    for (const entry of conversation.entries) {
        if (entry.kind !== 'event' || entry.type !== 'fileChange' || entry.status !== 'completed') continue
        const { deletions: eventDeletions, insertions: eventInsertions } = entry
        if (typeof eventDeletions !== 'number' || !Number.isSafeInteger(eventDeletions) || eventDeletions < 0) continue
        if (typeof eventInsertions !== 'number' || !Number.isSafeInteger(eventInsertions) || eventInsertions < 0) continue

        countedEvents += 1
        deletions += eventDeletions
        insertions += eventInsertions
    }

    return countedEvents > 0 ? { deletions, insertions } : null
}

function isInsideFolder(cardPath: string, folder: string) {
    const normalizedFolder = folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')

    return normalizedCardPath.startsWith(`${normalizedFolder}/`)
}

/** Use persisted project/release totals while deriving current and archived detail from loaded activity. */
export function projectAgentTokenUsage(
    snapshot: ProjectSnapshot | null,
    archivedFolder: string,
    summary: AgentTokenUsageSummary,
): ProjectAgentUsage {
    const activeCards = snapshot?.activeCards ?? []
    const backgroundCards = snapshot?.backgroundCards ?? []
    const currentUsage = sumAgentTokenUsage(activeCards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)))
    const archivedUsage = sumAgentTokenUsage(
        backgroundCards
            .filter((card) => isInsideFolder(card.path, archivedFolder))
            .map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)),
    )
    const releases = Object.entries(summary.releases)
        .map(([name, usage]) => ({ name, usage }))
        .sort((left, right) => left.name.localeCompare(right.name))

    return {
        archived: { name: 'Archived', usage: archivedUsage },
        current: { name: 'Current', usage: currentUsage },
        project: summary.projectUsage,
        releases,
    }
}

export type ActionUsageScope = 'actionCard' | 'conversation'

/** Owns shared usage scope for one action popup binding. */
export class ActionUsageScopeStore extends EventTarget {
    private scope: ActionUsageScope = 'actionCard'

    readonly getSnapshot = () => this.scope

    readonly subscribe = (onStoreChange: () => void) => {
        this.addEventListener('changed', onStoreChange)

        return () => this.removeEventListener('changed', onStoreChange)
    }

    toggle(conversationAvailable: boolean) {
        if (this.scope === 'actionCard' && !conversationAvailable) return

        this.publish(this.scope === 'actionCard' ? 'conversation' : 'actionCard')
    }

    useActionCardScope() {
        this.publish('actionCard')
    }

    private publish(scope: ActionUsageScope) {
        if (scope === this.scope) return

        this.scope = scope
        this.dispatchEvent(new Event('changed'))
    }
}

import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import type { ActionRunHistoryEntry } from '../../../../data/electron_action_bridge'
import { defaultLoadHistory } from '../popup/action_popup_defaults'

interface ActionHistorySnapshot {
    entries: ActionRunHistoryEntry[]
    error: string | null
}

type Listener = () => void

const INITIAL_SNAPSHOT: ActionHistorySnapshot = { entries: [], error: null }

/** Owns run-history loading for history-rendering leaves. */
export class ActionHistoryStore {
    private readonly action: ActionDefinition
    private readonly context: ActionContext
    private readonly listeners = new Set<Listener>()
    private request = 0
    private snapshot = INITIAL_SNAPSHOT

    constructor(action: ActionDefinition, context: ActionContext) {
        this.action = action
        this.context = context
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: Listener) => {
        this.listeners.add(listener)

        return () => this.listeners.delete(listener)
    }

    async load() {
        const request = this.request + 1
        this.request = request
        this.publish({ ...this.snapshot, error: null })
        try {
            const entries = await defaultLoadHistory(this.action, this.context)
            if (request === this.request) this.publish({ entries, error: null })
        } catch (error) {
            if (request !== this.request) return

            const message = error instanceof Error ? error.message : 'Could not load run history'
            this.publish({ ...this.snapshot, error: message })
        }
    }

    private publish(snapshot: ActionHistorySnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

